task.vi:
Cho biết chương trình sau làm gì:
Nhập hai số nguyên không âm x và y trong khoảng 1-20, sau đó chạy hai vòng lặp lồng nhau:
for (unsigned int i = 1; i <= y; ++i) {
   for (unsigned int j = 1; j <= x; ++j) { printf("%s", "@"); }
   puts("");
}

task.en:
Explain what the given program does:
Reads two unsigned integers x and y in the range 1-20, then runs nested loops:
for (unsigned int i = 1; i <= y; ++i) {
   for (unsigned int j = 1; j <= x; ++j) { printf("%s", "@"); }
   puts("");
}

example.code:
#include <iostream>

int main() {
    int sum = 0;
    // Correct loop without trailing semicolon:
    for (int x = 100; x <= 105; ++x) {
        sum += x;
    }
    std::cout << "Sum 100..105: " << sum << "\n";

    // Proper switch without accidental fallthrough:
    int value = 4;
    switch (value % 2) {
        case 0:
            std::cout << value << " is Even\n";
            break;
        case 1:
            std::cout << value << " is Odd\n";
            break;
    }
    return 0;
}

#include <iostream>

int main() {
    // Arithmetic progression: 20, 14, 8, 2, -4, -10
    std::cout << "Progression: ";
    for (int x = 20; x >= -10; x -= 6) {
        std::cout << x << (x > -10 ? " " : "\n");
    }

    // Geometric rendering: Triangle Pattern A and D (size 4)
    std::cout << "Triangle A (left):\n";
    for (int r = 1; r <= 4; ++r) {
        for (int c = 1; c <= r; ++c) {
            std::cout << "*";
        }
        std::cout << "\n";
    }

    std::cout << "Triangle D (right):\n";
    for (int r = 1; r <= 4; ++r) {
        for (int s = 1; s <= 4 - r; ++s) {
            std::cout << " ";
        }
        for (int c = 1; c <= r; ++c) {
            std::cout << "*";
        }
        std::cout << "\n";
    }
    return 0;
}
